// Paradas intermediárias complementares do trecho sul
const INTERMEDIATE_STOPS = [
  { name: "Praça da Paz (Bancários)", coords: [-7.1510, -34.8335] },
  { name: "Trevo / Viaduto de Mangabeira", coords: [-7.1578, -34.8242] },
];

function initMap() {
  const mapElement = document.getElementById('map');
  if (!mapElement) return;

  // Centro intermediário entre Campus I e Mangabeira
  map = L.map('map', {
    zoomControl: true,
    attributionControl: true
  }).setView([-7.1440, -34.8430], 14);

  // 1. Google Maps Ruas (Google Maps Padrão com rótulos e vias completas)
  const googleRoadLayer = L.tileLayer('https://mt1.google.com/vt/lyrs=m&x={x}&y={y}&z={z}', {
    maxZoom: 20,
    attribution: '&copy; Google Maps'
  });

  // 2. Google Maps Híbrido (Satélite Real HD + Vias e Nomes de Prédios)
  const googleHybridLayer = L.tileLayer('https://mt1.google.com/vt/lyrs=y&x={x}&y={y}&z={z}', {
    maxZoom: 20,
    attribution: '&copy; Google Maps'
  });

  // 3. Google Maps Satélite Puro
  const googleSatLayer = L.tileLayer('https://mt1.google.com/vt/lyrs=s&x={x}&y={y}&z={z}', {
    maxZoom: 20,
    attribution: '&copy; Google Maps'
  });

  // 4. OpenStreetMap
  const osmLayer = L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
    maxZoom: 19,
    attribution: '&copy; OpenStreetMap'
  });

  // Define Google Maps Ruas como camada ativa padrão
  googleRoadLayer.addTo(map);

  // Traçado viário realista: usa a geometria exata calculada via OSRM (curvas reais do asfalto)
  const fullRouteCoords = (window.OSRM_FULL_ROUTE && window.OSRM_FULL_ROUTE.length > 0)
    ? window.OSRM_FULL_ROUTE
    : ROUTE_POLYLINE;

  const campusLoopCoords = (window.OSRM_CAMPUS_LOOP && window.OSRM_CAMPUS_LOOP.length > 0)
    ? window.OSRM_CAMPUS_LOOP
    : CAMPUS_LOOP_POLYLINE;

  // Traçado estilo Google Maps Navigation (Dual-Stroke: Borda de asfalto + Núcleo vibrante)
  const routeOutline = L.polyline(fullRouteCoords, {
    color: '#174ea6',
    weight: 8,
    opacity: 0.95,
    lineCap: 'round',
    lineJoin: 'round'
  }).addTo(map);

  routeLine = L.polyline(fullRouteCoords, {
    color: '#4285f4',
    weight: 5,
    opacity: 1.0,
    lineCap: 'round',
    lineJoin: 'round'
  }).addTo(map);

  // Circuito interno das 12 paradas do Campus I
  const campusLoopLine = L.polyline(campusLoopCoords, {
    color: '#0ea5e9',
    weight: 3.5,
    opacity: 0.85,
    dashArray: '5, 7',
    lineCap: 'round',
    lineJoin: 'round'
  }).addTo(map);

  // Marcadores personalizados dos terminais estilo Google Maps (Teardrop Pins)
  const iconCCHLA = createGoogleTerminalIcon('Terminal CCHLA (Campus I)', false);
  const iconCI = createGoogleTerminalIcon('Terminal CI (Mangabeira)', true);

  L.marker(CCHLA_COORDS, { icon: iconCCHLA })
    .addTo(map)
    .bindPopup(`
      <div class="google-card-popup">
        <div class="gcard-header">
          <span class="gcard-badge" style="background: #1e40af;">Terminal Principal</span>
          <span class="gcard-campus">Campus I • UFPB</span>
        </div>
        <div class="gcard-title">Terminal CCHLA</div>
        <div class="gcard-desc">Ponto de parada e embarque no estacionamento do CCHLA / Praça da Alegria.</div>
        <div class="gcard-actions">
          <button class="gcard-btn-waiting" type="button" onclick="window.selectUserStop(5);">📍 Esperando aqui</button>
          <a class="gcard-btn-gmaps" href="https://www.google.com/maps/search/?api=1&query=${CCHLA_COORDS[0]},${CCHLA_COORDS[1]}" target="_blank" rel="noopener noreferrer">
            🌐 GMaps ↗
          </a>
        </div>
      </div>
    `, { className: 'google-leaflet-popup', closeButton: true });

  L.marker(CI_COORDS, { icon: iconCI })
    .addTo(map)
    .bindPopup(`
      <div class="google-card-popup">
        <div class="gcard-header">
          <span class="gcard-badge" style="background: #ea4335;">Terminal de Retorno</span>
          <span class="gcard-campus">Mangabeira</span>
        </div>
        <div class="gcard-title">Terminal CI</div>
        <div class="gcard-desc">Ponto final em frente ao Centro de Informática.</div>
        <div class="gcard-actions">
          <button class="gcard-btn-waiting" type="button" onclick="window.selectUserStop(101);">📍 Esperando aqui</button>
          <a class="gcard-btn-gmaps" href="https://www.google.com/maps/search/?api=1&query=${CI_COORDS[0]},${CI_COORDS[1]}" target="_blank" rel="noopener noreferrer">
            🌐 GMaps ↗
          </a>
        </div>
      </div>
    `, { className: 'google-leaflet-popup', closeButton: true });

  // Layer Group para as 12 Paradas do Campus I
  const campusStopsGroup = L.layerGroup();
  window.campusStopsMarkers = {};

  CAMPUS_BUS_STOPS.forEach(stop => {
    const stopIcon = createGoogleStopIcon(stop);

    const popupHtml = `
      <div class="google-card-popup">
        <div class="gcard-header">
          <span class="gcard-badge">Ponto #${stop.id}</span>
          <span class="gcard-campus">Campus I • UFPB</span>
        </div>
        <div class="gcard-title">${stop.name}</div>
        <div class="gcard-desc">${stop.desc}</div>
        <div class="gcard-meta">📍 Coordenadas: ${stop.coords[0].toFixed(5)}, ${stop.coords[1].toFixed(5)}</div>
        <div class="gcard-actions">
          <button class="gcard-btn-focus" type="button" onclick="window.focusStop(${stop.id});">🎯 Focar</button>
          <button class="gcard-btn-waiting" type="button" onclick="window.selectUserStop(${stop.id});">📍 Esperando aqui</button>
          <a class="gcard-btn-gmaps" href="https://www.google.com/maps/search/?api=1&query=${stop.coords[0]},${stop.coords[1]}" target="_blank" rel="noopener noreferrer">
            🌐 GMaps ↗
          </a>
        </div>
      </div>
    `;

    const marker = L.marker(stop.coords, { icon: stopIcon })
      .bindPopup(popupHtml, { className: 'google-leaflet-popup', closeButton: true })
      .bindTooltip(`<b>${stop.id}. ${stop.name}</b>`, {
        direction: 'top',
        offset: [0, -38],
        className: 'google-pin-tooltip'
      });

    marker.addTo(campusStopsGroup);
    marker.addTo(map);
    window.campusStopsMarkers[stop.id] = marker;
  });

  campusStopsGroup.addTo(map);

  // Marcadores discretos das paradas intermediárias dos Bancários
  INTERMEDIATE_STOPS.forEach(stop => {
    L.circleMarker(stop.coords, {
      radius: 6,
      fillColor: '#1a73e8',
      color: '#ffffff',
      weight: 2,
      opacity: 1,
      fillOpacity: 0.95
    })
    .addTo(map)
    .bindPopup(`<strong>Parada Intermediária:</strong><br>${stop.name}`);
  });

  // Controle de alternância de camadas e overlays (100% livres e sem exigência de chave API)
  const baseMaps = {
    "🗺️ Google Maps (Ruas)": googleRoadLayer,
    "🌐 Google Maps (Híbrido HD)": googleHybridLayer,
    "🛰️ Google Maps (Satélite)": googleSatLayer,
    "🧭 OpenStreetMap": osmLayer
  };

  const overlayMaps = {
    "🚏 12 Paradas do Campus I": campusStopsGroup,
    "🛣️ Rota do Ônibus (Curvas Reais)": routeLine,
    "🔄 Circuito Interno Campus I": campusLoopLine
  };

  L.control.layers(baseMaps, overlayMaps, { position: 'topright' }).addTo(map);

  // Garante marcador inicial do ônibus no ponto de origem
  updateBusMarker(CCHLA_COORDS[0], CCHLA_COORDS[1], 15.0, false);

  // Ajusta a visão para enquadrar perfeitamente todo o Campus I e a rota
  const allCoordinates = fullRouteCoords;
  map.fitBounds(L.latLngBounds(allCoordinates), { padding: [30, 30] });

  // Exporta referência global para redimensionamento dinâmico
  window.map = map;
  window.campusStopsGroup = campusStopsGroup;

  // Garante re-renderização completa dos blocos após montagem no DOM
  setTimeout(() => {
    if (map) map.invalidateSize();
  }, 250);
}

// Criação de Pin estilo Teardrop do Google Maps com sombra realista
function createGoogleStopIcon(stop) {
  const pinSvg = `
    <div class="google-pin-container" data-id="${stop.id}" title="${stop.id}. ${stop.name}">
      <svg class="google-pin-svg" width="32" height="42" viewBox="0 0 32 42" fill="none" xmlns="http://www.w3.org/2000/svg">
        <defs>
          <filter id="gpin-shadow-${stop.id}" x="-30%" y="-20%" width="160%" height="160%">
            <feDropShadow dx="0" dy="3.5" stdDeviation="2.5" flood-color="rgba(0,0,0,0.45)"/>
          </filter>
        </defs>
        <!-- Gota 3D estilizada estilo Google Maps -->
        <path d="M16 1C8.268 1 2 7.268 2 15C2 25.5 16 41 16 41C16 41 30 25.5 30 15C30 7.268 23.732 1 16 1Z" 
              fill="#1a73e8" stroke="#ffffff" stroke-width="1.5" filter="url(#gpin-shadow-${stop.id})"/>
        <!-- Círculo interior branco de alto contraste -->
        <circle cx="16" cy="14.5" r="9" fill="#ffffff" stroke="rgba(0,0,0,0.08)" stroke-width="1"/>
        <!-- Número da parada -->
        <text x="16" y="18.5" text-anchor="middle" font-family="'Inter', system-ui, -apple-system, sans-serif" font-size="11.5" font-weight="800" fill="#174ea6">${stop.id}</text>
      </svg>
    </div>
  `;

  return L.divIcon({
    className: 'custom-google-pin-marker',
    html: pinSvg,
    iconSize: [32, 42],
    iconAnchor: [16, 41],
    popupAnchor: [0, -41]
  });
}

// Criação de Pin estilo Teardrop para Terminais
function createGoogleTerminalIcon(name, isCI = false) {
  const color = isCI ? '#ea4335' : '#1e40af';
  const termSvg = `
    <div class="google-pin-container terminal-pin" title="${name}">
      <svg class="google-pin-svg" width="36" height="46" viewBox="0 0 36 46" fill="none" xmlns="http://www.w3.org/2000/svg">
        <defs>
          <filter id="gterm-shadow-${isCI ? 'ci' : 'cchla'}" x="-30%" y="-20%" width="160%" height="160%">
            <feDropShadow dx="0" dy="4" stdDeviation="3" flood-color="rgba(0,0,0,0.5)"/>
          </filter>
        </defs>
        <path d="M18 1C9.163 1 2 8.163 2 17C2 28.9 18 45 18 45C18 45 34 28.9 34 17C34 8.163 26.837 1 18 1Z" 
              fill="${color}" stroke="#ffffff" stroke-width="2" filter="url(#gterm-shadow-${isCI ? 'ci' : 'cchla'})"/>
        <circle cx="18" cy="16.5" r="10.5" fill="#ffffff"/>
        <text x="18" y="21.5" text-anchor="middle" font-size="13">🚏</text>
      </svg>
    </div>
  `;
  return L.divIcon({
    className: 'custom-google-pin-marker',
    html: termSvg,
    iconSize: [36, 46],
    iconAnchor: [18, 45],
    popupAnchor: [0, -45]
  });
}

let isAutoFollowActive = false;
let userHasInteractedWithMap = false;

function getAdjustedCenter(targetLatLng, targetZoom) {
  if (window.innerWidth <= 768) {
    const point = map.project(targetLatLng, targetZoom);
    const offsetY = window.innerHeight * 0.22;
    const adjustedPoint = L.point(point.x, point.y + offsetY);
    return map.unproject(adjustedPoint, targetZoom);
  } else {
    const point = map.project(targetLatLng, targetZoom);
    const offsetX = 190;
    const adjustedPoint = L.point(point.x - offsetX, point.y);
    return map.unproject(adjustedPoint, targetZoom);
  }
}

function updateBusMarker(lat, lon, accuracy = null, isCollab = false) {
  if (!map) return;

  const busColor = isCollab ? '#10b981' : '#2563eb';
  const pulseEffect = isCollab ? 'box-shadow: 0 0 14px #10b981;' : 'box-shadow: 0 0 10px #2563eb;';

  const busIcon = L.divIcon({
    className: 'custom-bus-icon',
    html: `
      <div id="bus-marker-element" style="
        background: ${busColor}; 
        color: #ffffff; 
        width: 38px; 
        height: 38px; 
        border-radius: 50%; 
        display: flex; 
        align-items: center; 
        justify-content: center; 
        font-size: 20px; 
        border: 3px solid #ffffff; 
        ${pulseEffect}
        transition: all 0.4s ease;
      ">🚌</div>
    `,
    iconSize: [38, 38],
    iconAnchor: [19, 19]
  });

  if (!busMarker) {
    busMarker = L.marker([lat, lon], { icon: busIcon }).addTo(map);
  } else {
    busMarker.setLatLng([lat, lon]);
    busMarker.setIcon(busIcon);
  }

  // Raio de acurácia do GPS
  if (accuracy && accuracy > 0) {
    if (!accuracyCircle) {
      accuracyCircle = L.circle([lat, lon], {
        radius: accuracy,
        color: busColor,
        fillColor: busColor,
        fillOpacity: 0.18,
        weight: 1.5
      }).addTo(map);
    } else {
      accuracyCircle.setLatLng([lat, lon]);
      accuracyCircle.setRadius(accuracy);
    }
  } else if (accuracyCircle) {
    map.removeLayer(accuracyCircle);
    accuracyCircle = null;
  }

  // Acompanhamento suave da câmera se modo Foco estiver ativo
  if (isAutoFollowActive) {
    const targetCenter = getAdjustedCenter(L.latLng(lat, lon), map.getZoom());
    map.panTo(targetCenter, { animate: true, duration: 0.6 });
  }
}

// Centraliza a visão do mapa suavemente no ônibus com compensação de painel (estilo Uber / Transit)
function recenterBus() {
  if (!map) return;
  
  if (!busMarker) {
    updateBusMarker(CCHLA_COORDS[0], CCHLA_COORDS[1], 15.0, false);
  }

  isAutoFollowActive = true;
  const targetLatLng = busMarker.getLatLng();
  const targetZoom = Math.max(map.getZoom(), 16);

  map.invalidateSize();
  const targetCenter = getAdjustedCenter(targetLatLng, targetZoom);
  map.flyTo(targetCenter, targetZoom, { duration: 0.8 });

  // Feedback visual no botão
  const btnRecenter = document.getElementById('btn-recenter-bus');
  if (btnRecenter) {
    btnRecenter.classList.add('focused-active');
    const label = btnRecenter.querySelector('.recenter-label');
    const prevText = label ? label.textContent : '';
    if (label) label.textContent = 'Seguindo Ônibus';
    setTimeout(() => {
      if (label && isAutoFollowActive) label.textContent = '🎯 Focado';
    }, 1800);
  }

  // Efeito de destaque no elemento visual do ônibus
  const markerElem = document.getElementById('bus-marker-element');
  if (markerElem) {
    markerElem.style.transform = 'scale(1.35)';
    setTimeout(() => {
      if (markerElem) markerElem.style.transform = 'scale(1)';
    }, 450);
  }
}

// Centraliza suavemente em uma parada específica e abre o popup
function focusStop(stopId) {
  if (!map) return;
  const marker = window.campusStopsMarkers && window.campusStopsMarkers[stopId];
  if (!marker) return;
  const latLng = marker.getLatLng();
  isAutoFollowActive = false;
  map.flyTo(latLng, 17, { duration: 0.8 });
  setTimeout(() => {
    marker.openPopup();
  }, 850);
}

// Enquadra a área de abrangência das 12 paradas do Campus I
function focusCampusArea() {
  if (!map) return;
  isAutoFollowActive = false;
  const campusBounds = L.latLngBounds(CAMPUS_BUS_STOPS.map(s => s.coords));
  map.fitBounds(campusBounds, { padding: [50, 50] });
}

let userWaitingMarker = null;

// Seleciona a parada de espera do usuário e destaca no mapa com halo pulsante
function selectUserStop(stopId) {
  if (!map) return;
  stopId = parseInt(stopId, 10);

  // Encontra as coordenadas correspondentes
  let coords = null;
  let stopName = '';
  if (stopId === 100) {
    coords = [-7.1510, -34.8335];
    stopName = 'Praça da Paz (Bancários)';
  } else if (stopId === 101) {
    coords = CI_COORDS;
    stopName = 'Terminal CI (Mangabeira)';
  } else {
    const stop = CAMPUS_BUS_STOPS.find(s => s.id === stopId);
    if (stop) {
      coords = stop.coords;
      stopName = stop.name;
    }
  }

  if (!coords) return;

  // Atualiza marcador de halo do usuário
  if (userWaitingMarker) {
    map.removeLayer(userWaitingMarker);
  }

  const waitingHaloIcon = L.divIcon({
    className: 'custom-waiting-halo',
    html: `
      <div class="user-waiting-halo-icon" title="Você está esperando aqui: ${stopName}">
        <div class="waiting-pulse-circle">
          <span class="waiting-user-avatar">👤</span>
        </div>
      </div>
    `,
    iconSize: [50, 50],
    iconAnchor: [25, 25]
  });

  userWaitingMarker = L.marker(coords, { icon: waitingHaloIcon, zIndexOffset: 950 }).addTo(map);

  // Sincroniza o select do usuário na interface
  const selectElem = document.getElementById('user-stop-select');
  if (selectElem && selectElem.value !== String(stopId)) {
    selectElem.value = String(stopId);
    selectElem.dispatchEvent(new Event('change'));
  }

  isAutoFollowActive = false;
  map.flyTo(coords, 16.5, { duration: 0.8 });

  try {
    localStorage.setItem('locbus_waiting_stop_id', String(stopId));
  } catch (e) {}
}

// Marca visualmente a chegada do ônibus em uma parada com badge animado
function markStopArrival(stopId) {
  stopId = parseInt(stopId, 10);
  const container = document.querySelector(`.google-pin-container[data-id="${stopId}"]`);
  if (container) {
    let badge = container.querySelector('.stop-arrived-pulse-badge');
    if (!badge) {
      badge = document.createElement('div');
      badge.className = 'stop-arrived-pulse-badge';
      badge.innerHTML = '🚌 Chegou!';
      container.appendChild(badge);
    }
    setTimeout(() => {
      if (badge && badge.parentNode) {
        badge.parentNode.removeChild(badge);
      }
    }, 45000);
  }
}

window.recenterBus = recenterBus;
window.focusStop = focusStop;
window.focusCampusArea = focusCampusArea;
window.selectUserStop = selectUserStop;
window.markStopArrival = markStopArrival;
window.CAMPUS_BUS_STOPS = CAMPUS_BUS_STOPS;

// Inicializa quando o DOM estiver pronto
document.addEventListener('DOMContentLoaded', () => {
  initMap();
  const btnRecenter = document.getElementById('btn-recenter-bus');
  if (btnRecenter) {
    btnRecenter.addEventListener('click', recenterBus);
  }

  const btnFocusCampus = document.getElementById('btn-focus-campus');
  if (btnFocusCampus) {
    btnFocusCampus.addEventListener('click', focusCampusArea);
  }

  // Se o usuário arrastar o mapa manualmente, desativa o auto-follow para não conflitar com a navegação do usuário
  if (map) {
    map.on('dragstart', () => {
      isAutoFollowActive = false;
      userHasInteractedWithMap = true;
      if (btnRecenter) {
        btnRecenter.classList.remove('focused-active');
        const label = btnRecenter.querySelector('.recenter-label');
        if (label) label.textContent = 'Focar Ônibus';
      }
    });
  }
});

